import math, json

def val(k, N=60):
    p = 1.0
    for n in range(1, N):
        p *= math.cos(math.pi / (k * 2**n))
    return math.pi * p / math.sin(math.pi / k)

undefined = [0, 1, -1]  # k=0: division by zero; |k|=1: sin(pi/k)=0 (and a cos factor is 0)
checked = 0
bad = []
for k in range(-500, 501):
    if k in undefined:
        continue
    v = val(k)
    checked += 1
    if abs(v - k) > 1e-8 * max(1, abs(k)):
        bad.append(k)

# The identity: prod_{n>=1} cos(x/2^n) = sin(x)/x with x = pi/k gives expression = k
ans = ("Yes, wherever it is defined: the expression equals k (an integer) via "
       "prod cos(x/2^n)=sin(x)/x. It is undefined for k=0 and k=+-1 (0/0 or division by zero).")
print(json.dumps({
    "final_answer": ans,
    "evidence": {"checked_k": checked, "mismatches": bad, "undefined_k": undefined,
                 "sample": {str(k): val(k) for k in (2, 3, 7, -5)}}
}))
